fn find_project_root() -> anyhow::Result<PathBuf> {
    let mut candidates = Vec::new();
    if let Ok(exe) = std::env::current_exe() {
        if let Some(parent) = exe.parent() {
            candidates.push(parent.to_path_buf());
        }
    }
    candidates.push(std::env::current_dir()?);

    for candidate in candidates {
        if let Some(root) = find_hotpaths_ancestor(&candidate) {
            return Ok(root);
        }
    }

    anyhow::bail!("could not find `hotpaths` directory")
}

fn find_hotpaths_ancestor(start: &Path) -> Option<PathBuf> {
    let mut dir = start.to_path_buf();
    loop {
        if dir.join("hotpaths").join("primordial").is_dir() {
            return Some(dir);
        }
        if !dir.pop() {
            return None;
        }
    }
}

